from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, ttl_seconds, clock):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.clock = clock
        self._entries = OrderedDict()  # key -> (value, expires_at)

    def _now(self):
        return self.clock()

    def _expired(self, key, now):
        return self._entries[key][1] < now

    def _evict(self):
        """Evict entries until within capacity.

        Dead (expired) entries are dropped first since they are no longer
        live; if more room is still needed, the least-recently-used live
        entry is evicted.
        """
        now = self._now()
        for key in [k for k in self._entries if self._expired(k, now)]:
            del self._entries[key]
        while len(self._entries) > self.capacity:
            del self._entries[next(iter(self._entries))]

    def get(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return None
        value, expires_at = entry
        if self._now() > expires_at:
            del self._entries[key]
            return None
        self._entries.move_to_end(key)  # refresh recency for hits
        return value

    def put(self, key, value):
        now = self._now()
        if key in self._entries:
            self._entries[key] = (value, now + self.ttl_seconds)
            self._entries.move_to_end(key)
        else:
            self._entries[key] = (value, now + self.ttl_seconds)
        if len(self._entries) > self.capacity:
            self._evict()

